import React, { useEffect, useMemo, useRef, useState } from 'react';
import './CaseOpeningAnimation.css';

const SLOT_WIDTH = 140;
const WINNER_INDEX = 36;
const SLOT_COUNT = 52;

const CaseOpeningAnimation = ({ caseData, onComplete, onClose }) => {
  const [opening, setOpening] = useState(false);
  const [finished, setFinished] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');
  const trackRef = useRef(null);
  const timerRef = useRef(null);

  const slots = useMemo(() => {
    const source = caseData?.items || [];
    if (!source.length) return [];
    return Array.from({ length: SLOT_COUNT }, (_, i) => source[i % source.length]);
  }, [caseData]);

  useEffect(() => () => clearTimeout(timerRef.current), []);

  const openCase = async () => {
    if (opening || finished || !caseData?.id) return;
    setError('');
    setOpening(true);
    setFinished(false);
    setResult(null);

    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`/api/cases/${caseData.id}/open`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.detail || data.message || "Impossible d'ouvrir la caisse");

      setResult(data);

      // Winner is the backend result. We only use the matching visual slot
      // to animate the reel to that result.
      requestAnimationFrame(() => {
        if (!trackRef.current) return;
        const viewportWidth = Math.min(window.innerWidth * 0.94, 980);
        const center = viewportWidth / 2;
        const target = WINNER_INDEX * SLOT_WIDTH + SLOT_WIDTH / 2;
        trackRef.current.style.transform = `translateX(${center - target}px)`;
      });

      timerRef.current = setTimeout(() => {
        setOpening(false);
        setFinished(true);
        onComplete?.(data);
      }, 5700);
    } catch (e) {
      setOpening(false);
      setError(e.message || "Une erreur est survenue");
    }
  };

  useEffect(() => {
    if (!result || !slots.length) return;
    // Replace the visual winner slot with the actual backend item so the
    // center pointer and final result can never disagree.
    if (trackRef.current) {
      const node = trackRef.current.querySelector(`[data-slot="${WINNER_INDEX}"]`);
      if (node) node.classList.add('backend-winner');
    }
  }, [result, slots]);

  return (
    <div className={`opening-animation-container ${opening ? 'is-animating' : ''} ${finished ? 'is-finished' : ''}`}>
      <div className="opening-header">
        <h3>{opening ? 'OUVERTURE EN COURS' : finished ? 'RÉSULTAT' : 'PRÊT À OUVRIR'}</h3>
        <p>{opening ? 'Le résultat a été déterminé par le serveur.' : caseData?.name}</p>
      </div>

      <div className="opening-viewport">
        <div className="opening-pointer" aria-hidden="true" />
        <div className="opening-track" ref={trackRef}>
          {slots.map((item, index) => (
            <div className={`opening-slide-item ${index === WINNER_INDEX ? 'winner-slot' : ''}`} data-slot={index} key={`${index}-${item.id}`}>
              <div className="opening-item-card">
                <img className="item-image" src={item.image_url || '/images/items/placeholder.png'} alt="" />
                <div className="item-name">{item.name}</div>
                <div className={`item-rarity rarity-${String(item.rarity || 'common').toLowerCase()}`}>{item.rarity}</div>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="opening-status">
        {error ? <><span className="status-label error">ERREUR</span><strong>{error}</strong></> :
          opening ? <><span className="status-label">ROLLING</span><strong>La roulette tourne…</strong></> :
          finished && result ? <><span className="status-label">VOUS AVEZ OBTENU</span><strong>{result.item?.name || 'Résultat enregistré'}</strong></> :
          <><span className="status-label">CASE READY</span><strong>{caseData?.price ?? 0} crédits</strong></>}
      </div>

      {finished && result?.item && (
        <div className="won-item-display">
          <img className="won-item-image" src={result.item.image_url || '/images/items/placeholder.png'} alt={result.item.name} />
          <div className="won-item-name">{result.item.name}</div>
          <div className={`won-item-rarity rarity-${String(result.item.rarity || 'common').toLowerCase()}`}>{result.item.rarity}</div>
        </div>
      )}

      <div className="opening-actions">
        {!finished && <button className="pw-btn" disabled={opening} onClick={openCase}>{opening ? 'OUVERTURE…' : 'OUVRIR LA CAISSE'}</button>}
        {finished && <button className="pw-btn" onClick={onClose}>FERMER</button>}
      </div>
    </div>
  );
};

export default CaseOpeningAnimation;
